   309  /* returns the first match of a section that it name matches 'name' parameter */
   310  struct flb_cf_section *flb_cf_section_get_by_name(struct flb_cf *cf, char *name)
   311  {
   312      struct mk_list *head;
   313      struct flb_cf_section *s;
   314
   315      mk_list_foreach(head, &cf->sections) {
   316          s = mk_list_entry(head, struct flb_cf_section, _head);
   317          if (strcasecmp(s->name, name) == 0) {
   318              return s;
   319          }
   320      }
   300      }
   301      else {
   302          ctx->file = NULL;
   303          ctx->root_path = NULL;
   304      }
   305
   306      ctx->level = 0;
   307      mk_list_init(&ctx->metas);
   308      mk_list_init(&ctx->sections);
   309      mk_list_init(&ctx->includes);
   310
   311      return 0;
   312  }
