   314  static void local_exit(struct local_ctx *ctx)
   315  {
   316      struct mk_list *tmp;
   317      struct mk_list *head;
   318      struct local_file *f;
   319
   320      mk_list_foreach_safe(head, tmp, &ctx->includes) {
   321          f = mk_list_entry(head, struct local_file, _head);
   322          flb_sds_destroy(f->path);
