   336  static int is_file_included(struct local_ctx *ctx, const char *path)
   337  {
   338      struct mk_list *head;
   339      struct local_file *file;
   340
   341      mk_list_foreach(head, &ctx->includes) {
   342          file = mk_list_entry(head, struct local_file, _head);
   343          if (strcmp(file->path, path) == 0) {
   344              return FLB_TRUE;
   345          }
   346      }
   347
   348      return FLB_FALSE;
   349  }
