   351  static int check_indent(const char *line, const char *indent, int *out_level)
   352  {
   353      int extra = 0;
   354      int level = 0;
   355
   356      while (*line == *indent && *indent) {
   357          line++;
   358          indent++;
   359          level++;
   360      }
   361
   362      if (*indent != '\0') {
   363          if (isblank(*line)) {
   364              flb_error("[config] inconsistent use of tab and space");
   365          }
   366          else {
   367              flb_error("[config] indentation level is too low");
   368          }
   369          return INDENT_ERROR;;
   370      }
   371
   372      if (isblank(*line)) {
   373          /* check if we have a 'group' key/value line */
   374          while (isblank(*line)) {
   375              line++;
   376              extra++;
   377          }
   378
   379          if (extra == level) {
   380              *out_level = level + extra;
   381              return INDENT_GROUP_CONTENT;
   382          }
   383
   384          flb_error("[config] extra indentation level found");
   385          return -1;
   386      }
   387
   388      *out_level = level;
   389      return INDENT_OK;
   390  }
