   392  static int read_config(struct flb_cf *cf, struct local_ctx *ctx,
   393                         char *cfg_file, char *in_data, size_t in_size)
   394  {
   395      int i;
   396      int len;
   397      int ret;
   398      int end;
   399      int level;
   400      int line = 0;
   401      int indent_len = -1;
   402      int n_keys = 0;
   403      char *key = NULL;
   404      int key_len;
   405      char *val = NULL;
   406      int val_len;
   407      char *buf;
   408      char tmp[PATH_MAX];
   409      flb_sds_t section = NULL;
   410      flb_sds_t indent = NULL;
   411      struct stat st;
   412      struct local_file *file;
   413      struct flb_cf_meta *meta;
   414      struct flb_cf_section *current_section = NULL;
   415      struct flb_cf_group *current_group = NULL;
   416
   417      struct flb_kv *kv;
   418      FILE *f = NULL;
   419
   420      /* Check if the path exists (relative cases for included files) */
   421  #ifndef FLB_HAVE_STATIC_CONF
   422      if (ctx->level >= 0) {
   423          ret = stat(cfg_file, &st);
   424          if (ret == -1 && errno == ENOENT) {
   425              /* Try to resolve the real path (if exists) */
   426              if (cfg_file[0] == '/') {
   427                  return -1;
   428              }
   429
   430              if (ctx->root_path) {
   431                  snprintf(tmp, PATH_MAX, "%s/%s", ctx->root_path, cfg_file);
   432                  cfg_file = tmp;
   433              }
   434          }
   435      }
   436  #endif
   437
   438      /* Check this file have not been included before */
   439      ret = is_file_included(ctx, cfg_file);
   440      if (ret) {
   441          flb_error("[config] file already included %s", cfg_file);
   442          return -1;
   443      }
   444      ctx->level++;
   445
   446  #ifndef FLB_HAVE_STATIC_CONF
   447      /* Open configuration file */
   448      if ((f = fopen(cfg_file, "r")) == NULL) {
   449          flb_warn("[config] I cannot open %s file", cfg_file);
   450          return -1;
   451      }
   452  #endif
   453
   454      /* Allocate temporal buffer to read file content */
   455      buf = flb_malloc(FLB_CF_BUF_SIZE);
   456      if (!buf) {
   457          flb_errno();
   458          goto error;
   459      }
   460
   461  #ifdef FLB_HAVE_STATIC_CONF
   462      /*
   463       * a static configuration comes from a buffer, so we use the static_fgets()
   464       * workaround to retrieve the lines.
   465       */
   466      size_t off = 0;
   467      while (static_fgets(buf, FLB_CF_BUF_SIZE, in_data, &off)) {
   468  #else
   469      /* normal mode, read lines into a buffer */
   470      while (fgets(buf, FLB_CF_BUF_SIZE, f)) {
   471  #endif
   472          len = strlen(buf);
   473          if (len > 0 && buf[len - 1] == '\n') {
   474              buf[--len] = 0;
   475              if (len && buf[len - 1] == '\r') {
   476                  buf[--len] = 0;
   477              }
   478          }
   479  #ifndef FLB_HAVE_STATIC_CONF
   480          else {
   481              /*
   482               * If we don't find a break line, validate if we got an EOF or not. No EOF
   483               * means that the incoming string is not finished so we must raise an
   484               * exception.
   485               */
   486              if (!feof(f)) {
   487                  config_error(cfg_file, line, "length of content has exceeded limit");
   488                  goto error;
   489              }
   490          }
   491  #endif
   492
   493          /* Line number */
   494          line++;
   495
   496          if (!buf[0]) {
   497              continue;
   498          }
   499
   500          /* Skip commented lines */
   501          if (buf[0] == '#') {
   502              continue;
   503          }
   504
   505          if (len > 9 && strncasecmp(buf, "@INCLUDE ", 9) == 0) {
   506              if (strchr(buf + 9, '*') != NULL) {
   507                  ret = read_glob(cf, ctx, buf + 9);
   508              }
   509              else {
   510                  ret = read_config(cf, ctx, buf + 9, NULL, 0);
   511              }
   512              if (ret == -1) {
   513                  ctx->level--;
   514                  if (indent) {
   515                      flb_sds_destroy(indent);
   516                      indent = NULL;
   517                  }
   518                  goto error;
   519              }
   520              continue;
